def _decode_text(payload: str) -> str:
    raw = base64.b64decode("".join(payload.split()))
    return gzip.decompress(raw).decode("utf-8-sig")


def _to_float(value: Any, default: float = 0.0) -> float:
    if value is None or value == "":
        return default
    try:
        x = float(value)
    except Exception:
        return default
    if math.isnan(x) or math.isinf(x):
        return default
    return x


def _load_daily() -> list[dict[str, Any]]:
    text = _decode_text(_DAILY_B64)
    rows: list[dict[str, Any]] = []
    for row in csv.DictReader(io.StringIO(text)):
        item: dict[str, Any] = dict(row)
        item["date"] = str(item.get("date", ""))[:10]
        for key, value in list(item.items()):
            if key != "date" and key not in {"strategy_id", "candidate"}:
                item[key] = _to_float(value)
        rows.append(item)
    rows.sort(key=lambda x: x["date"])
    return rows


def _load_metrics_payload() -> dict[str, Any]:
    return json.loads(_decode_text(_METRICS_B64))


_DAILY = _load_daily()
_PAYLOAD = _load_metrics_payload()
_METRICS = _PAYLOAD.get("metrics", [])
_META = _PAYLOAD.get("meta", {})


def pct(value: Any, digits: int = 2) -> str:
    return f"{_to_float(value) * 100:.{digits}f}%"


def num(value: Any, digits: int = 3) -> str:
    return f"{_to_float(value):.{digits}f}"


def _parse_date(value: str) -> datetime | None:
    try:
        return datetime.strptime(value[:10], "%Y-%m-%d")
    except Exception:
        return None


def _date_window(query: str, rows: list[dict[str, Any]]) -> tuple[str, list[dict[str, Any]]]:
    if not rows:
        return "empty", []
    compact = query.replace(" ", "")
    end = _parse_date(rows[-1]["date"])
    if end is None:
        return "all", rows
    years: int | None = None
    if "\u5341\u5e74" in compact or "10\u5e74" in compact or "10Y" in query.upper():
        years = 10
    elif "\u4e94\u5e74" in compact or "5\u5e74" in compact or "5Y" in query.upper():
        years = 5
    elif "\u4e09\u5e74" in compact or "3\u5e74" in compact or "3Y" in query.upper():
        years = 3
    elif "\u4e00\u5e74" in compact or "1\u5e74" in compact or "1Y" in query.upper() or "\u8fc7\u53bb\u4e00\u5e74" in compact:
        years = 1
    dates = re.findall(r"20\d{2}-\d{1,2}-\d{1,2}", query)
    if len(dates) >= 2:
        start = _parse_date(dates[0])
        finish = _parse_date(dates[1])
        if start and finish:
            subset = [r for r in rows if start <= _parse_date(r["date"]) <= finish]
            return f"{dates[0]} to {dates[1]}", subset
    if years is not None:
        start = end - timedelta(days=int(years * 365.25))
        return f"last_{years}y", [r for r in rows if (_parse_date(r["date"]) or end) >= start]
    return "full", rows


def _metrics_for_rows(rows: list[dict[str, Any]]) -> dict[str, float]:
    if not rows:
        return {"ann_return": 0.0, "max_dd": 0.0, "final_nav": 1.0, "avg_weight": 0.0, "avg_turnover": 0.0, "holding_day_ratio": 0.0, "cost_total": 0.0}
    nav = 1.0
    peak = 1.0
    max_dd = 0.0
    weights: list[float] = []
    turnovers: list[float] = []
    holding = 0
    cost_total = 0.0
    for row in rows:
        nav *= 1.0 + _to_float(row.get("return"))
        peak = max(peak, nav)
        max_dd = min(max_dd, nav / peak - 1.0)
        weight = _to_float(row.get("weight"))
        weights.append(abs(weight))
        turnovers.append(_to_float(row.get("turnover")))
        holding += 1 if abs(weight) > 1e-12 else 0
        cost_total += _to_float(row.get("cost"))
    years = len(rows) / ANNUAL_DAYS
    ann = nav ** (1.0 / years) - 1.0 if years > 0 and nav > 0 else 0.0
    return {
        "ann_return": ann,
        "max_dd": max_dd,
        "final_nav": nav,
        "avg_weight": sum(weights) / len(weights),
        "avg_turnover": sum(turnovers) / len(turnovers),
        "holding_day_ratio": holding / len(rows),
        "cost_total": cost_total,
    }


def _metric_by_segment(segment: str) -> dict[str, Any] | None:
    for row in _METRICS:
        if str(row.get("segment")) == segment:
            return row
    return None


def _exposure_text(weight: float) -> str:
    if abs(weight) <= 1e-12:
        return "\u7a7a\u4ed3"
    return f"\u505a\u591a{LONG_LEG} / \u505a\u7a7a{SHORT_LEG}\uff0c\u6267\u884c\u4ed3\u4f4d {pct(weight, 1)}"


def render_signal(live: bool = False) -> str:
    if not _DAILY:
        return "## \u4fe1\u53f7\n\n\u65e0\u5185\u5d4c\u6570\u636e\u3002\n"
    row = _DAILY[-1]
    title = "\u5b9e\u65f6\u4fe1\u53f7" if live else "\u4fe1\u53f7"
    lines = [f"## {title}", ""]
    if live:
        lines.append("- \u6570\u636e\u6a21\u5f0f\uff1aPoe \u5185\u5d4c\u786e\u8ba4\u65e5\u9891\u4ea7\u7269\uff1b\u5f53\u524d\u811a\u672c\u4e0d\u6293\u53d6\u76d8\u4e2d\u884c\u60c5\u3002")
    lines.extend([
        f"- \u65e5\u671f\uff1a`{row['date']}`",
        f"- \u65b9\u5411\uff1a`{DIRECTION}`",
        f"- \u72b6\u6001\uff1a{_exposure_text(_to_float(row.get('weight')))}",
        f"- \u76ee\u6807\u6ce2\u52a8\u7387\u540e\u4ed3\u4f4d\uff1a{pct(row.get('pre_volume_weight'), 1)}",
        f"- \u6210\u4ea4\u91cf\u8fc7\u6ee4\uff1a{'\u5f00\u542f' if _to_float(row.get('volume_on')) > 0 else '\u5173\u95ed'}\uff0cmult={num(row.get('volume_mult'), 2)}\uff0cindicator={num(row.get('volume_indicator'), 3)}",
        f"- score={num(row.get('signal_score'), 3)}\uff0ctarget-vol scale={num(row.get('target_vol_applied_scale'), 3)}",
        f"- NAV={num(row.get('nav'), 4)}",
    ])
    return "\n".join(lines) + "\n"


def render_params(live: bool = False) -> str:
    line = _META.get("line", {})
    volume = _META.get("volume_filter", {})
    tv = _META.get("target_vol", {})
    lines = ["## \u53c2\u6570", ""]
    if live:
        lines.append("- \u5b9e\u65f6\u53c2\u6570\u4e0e\u786e\u8ba4\u4fe1\u53f7\u53c2\u6570\u4e00\u81f4\uff1bPoe \u811a\u672c\u4f7f\u7528\u5185\u5d4c\u786e\u8ba4\u65e5\u9891\u4ea7\u7269\u3002")
    lines.extend([
        f"- strategy_id\uff1a`{STRATEGY_ID}`",
        f"- \u65b9\u5411\uff1a`{DIRECTION}`",
        f"- \u6b63\u5f0f\u8d77\u70b9\uff1a`{_META.get('formal_start', '2014-10-17')}`",
        f"- \u4fe1\u53f7\uff1abias_ma={line.get('bias_ma')}\uff0cmom_day={line.get('mom_day')}\uff0cweight_end={line.get('weight_end')}\uff0cscore>{line.get('score_threshold')}\uff0cabs_ma={line.get('abs_ma')}\uff0cabs>{line.get('abs_threshold')}",
        f"- \u76ee\u6807\u6ce2\u52a8\u7387\uff1atarget={pct(tv.get('target_vol'))}\uff0cwindow={tv.get('vol_window')}\uff0cmaxLev={tv.get('max_leverage')}\uff0cdeadband={pct(tv.get('scale_deadband'))}",
        f"- \u6210\u4ea4\u91cf\u8fc7\u6ee4\uff1a{volume.get('feature')}\uff0cwindow={volume.get('window')}\uff0cthreshold={volume.get('threshold')}\uff0cconfirm_days={volume.get('confirm_days')}\uff0cscale={volume.get('scale')}",
        f"- \u6210\u672c\uff1a\u53cc\u817f\uff0c\u5355\u8fb9 {pct(_META.get('cost_model', {}).get('one_way_commission'))}",
    ])
    return "\n".join(lines) + "\n"


def render_performance(query: str) -> str:
    label, rows = _date_window(query, _DAILY)
    if label == "full":
        segments = ["full", "last_10y", "last_5y", "last_3y", "last_1y"]
        lines = ["## \u8868\u73b0", "", "| \u7a97\u53e3 | \u5e74\u5316 | \u6700\u5927\u56de\u64a4 | NAV | \u6301\u4ed3\u5360\u6bd4 |", "|---|---:|---:|---:|---:|"]
        for seg in segments:
            row = _metric_by_segment(seg)
            if row:
                lines.append(f"| {seg} | {pct(row.get('ann_return'))} | {pct(row.get('max_dd'))} | {num(row.get('final_nav'), 4)} | {pct(row.get('holding_day_ratio'))} |")
        return "\n".join(lines) + "\n"
    metric_row = _metric_by_segment(label)
    if metric_row is not None:
        lines = [
            "## \u8868\u73b0",
            "",
            f"- \u7a97\u53e3\uff1a`{label}`",
            f"- \u5e74\u5316\u6536\u76ca\uff1a{pct(metric_row.get('ann_return'))}",
            f"- \u6700\u5927\u56de\u64a4\uff1a{pct(metric_row.get('max_dd'))}",
            f"- NAV\uff1a{num(metric_row.get('final_nav'), 4)}",
            f"- \u6301\u4ed3\u5360\u6bd4\uff1a{pct(metric_row.get('holding_day_ratio'))}",
        ]
        return "\n".join(lines) + "\n"
    m = _metrics_for_rows(rows)
    lines = ["## \u8868\u73b0", "", f"- \u7a97\u53e3\uff1a`{label}`\uff0c\u4ea4\u6613\u65e5 `{len(rows)}`", f"- \u5e74\u5316\u6536\u76ca\uff1a{pct(m['ann_return'])}", f"- \u6700\u5927\u56de\u64a4\uff1a{pct(m['max_dd'])}", f"- NAV\uff1a{num(m['final_nav'], 4)}", f"- \u6301\u4ed3\u5360\u6bd4\uff1a{pct(m['holding_day_ratio'])}"]
    return "\n".join(lines) + "\n"


def render_history() -> str:
    lines = ["## \u6700\u8fd1\u4fe1\u53f7", ""]
    for row in _DAILY[-8:]:
        lines.append(f"- {row['date']}: weight={pct(row.get('weight'), 1)}, volume_on={int(_to_float(row.get('volume_on')))}, score={num(row.get('signal_score'), 2)}")
    return "\n".join(lines) + "\n"


def render_query(query: str) -> str:
    text = str(query or "").strip()
    compact = text.replace(" ", "")
    if "\u53c2\u6570" in compact and "\u5b9e\u65f6" in compact:
        return render_params(live=True)
    if "\u53c2\u6570" in compact:
        return render_params(live=False)
    if "\u5386\u53f2" in compact and "\u4fe1\u53f7" in compact:
        return render_history()
    if "\u8868\u73b0" in compact or "\u6536\u76ca" in compact or "\u56de\u64a4" in compact:
        return render_performance(text)
    if "\u5b9e\u65f6" in compact and "\u4fe1\u53f7" in compact:
        return render_signal(live=True)
    if "\u4fe1\u53f7" in compact:
        return render_signal(live=False)
    return render_signal(live=False)


def _write_query_response(msg: Any, query: str) -> None:
    try:
        msg.write(render_query(query))
    except Exception as exc:
        msg.write("## \u67e5\u8be2\u5931\u8d25\n\n")
        msg.write(f"`{exc}`\n")


async def get_response(request: Any):  # pragma: no cover - Poe runtime entrypoint
    query = getattr(request, "query", None) or getattr(request, "text", "")
    with poe.start_message() as msg:
        _write_query_response(msg, str(query))
        return msg


def run() -> int:
    query_obj = getattr(poe, "query", None)
    query = getattr(query_obj, "text", "") if query_obj is not None else ""
    query = str(query).strip() or "\u4fe1\u53f7"
    with poe.start_message() as msg:
        _write_query_response(msg, query)
    return 0


if __name__ == "__main__":
    raise SystemExit(run())
